/// Returns the lower-bound insertion index for `x` within the sorted subrange
/// `a[lo..hi)`. The result `k` satisfies `lo <= k <= hi`, and:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    assert!(lo <= hi);
    assert!(hi <= a.len());

    let mut left = lo;
    let mut right = hi; // exclusive

    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left
}

/// Computes the lower bound of `x` considering only the first 1000 elements of `a`.
/// Assumes `a.len() >= 1000` and that `a[0..1000)` is sorted nondecreasing.
fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000);
    search_range_helper(a, x, 0, 1000)
}